"use strict";

// The vulnerable sink the advisory names. Every re-exporting entrypoint in
// this fixture reaches it only through the callable it RE-EXPORTS, so
// entrypoint root derivation is the only thing standing between the
// analyzer and the truth.
function dangerousOp(input) {
  return "danger:" + input;
}

// A second export nothing in this fixture ever calls, for the Family C
// positive control.
function neverCalled(input) {
  return "never:" + input;
}

exports.dangerousOp = dangerousOp;
exports.neverCalled = neverCalled;
